import PDFDocument from "pdfkit";
import type { CompanyView } from "@/lib/guias/company-profile";
import { companyLogo, plain } from "@/lib/guias/corte";
import { hasLithiumUn, isLithiumPi, lithiumSectionIIStatement } from "@/lib/guias/dg";
import type { GuiaPrintOptions, GuiaRecord } from "@/lib/guias/files";
import { SECURITY_LETTER_COPIES } from "@/lib/guias/magaya-docs";
import { formatFlightDate } from "@/lib/sheets/layout";

export type ChecklistRow = {
  /** "auto" documents are generated by Guías and travel in this package. "paper" ones must be collected. */
  source: "auto" | "paper";
  title: string;
  note: string;
};

export type ChecklistInput = {
  awb: string;
  bup: boolean;
  dangerousGoods: boolean;
  unNumbers: string;
  /** Packing instruction of Section II lithium batteries. No DGD for these. */
  lithiumPi?: string | null;
  goods: string;
  hasTrucker: boolean;
};

/**
 * The documents a shipment needs. The CCSF and the CCSP are listed only for a BUP, and the DG papers only
 * when the guía declares dangerous goods.
 */
export function checklistRows(input: ChecklistInput): ChecklistRow[] {
  const sectionII = isLithiumPi(input.lithiumPi);
  const lithium = sectionII || hasLithiumUn(input.unNumbers) || /lithium|litio/i.test(input.goods);
  const rows: ChecklistRow[] = [
    { source: "auto", title: "Air Waybill (12 pages)", note: input.awb ? `Number ${input.awb}` : "Issue the guía to get the number" },
    { source: "auto", title: "Cargo labels, one per piece", note: input.awb ? "Carry the AWB number" : "Issue the guía first, or print them from a draft" },
    { source: "auto", title: "Delivery order (DO)", note: input.hasTrucker ? "Trucker entered" : "Enter the trucker first" },
    { source: "auto", title: "Pickup order", note: input.hasTrucker ? "Trucker entered" : "Enter the trucker first" },
    { source: "auto", title: "TSA letter, known shipper", note: "Use this one or the unknown shipper letter, as it applies" },
    { source: "auto", title: "TSA letter, unknown shipper", note: "Use this one or the known shipper letter, as it applies" },
  ];
  if (input.bup) {
    rows.push(
      { source: "auto", title: "CCSF certificate (Kope)", note: `BUP. ${SECURITY_LETTER_COPIES} copies` },
      { source: "auto", title: "CCSP certification (ACK)", note: `BUP. ${SECURITY_LETTER_COPIES} copies` },
    );
  }
  if (lithium) rows.push({ source: "auto", title: "Lithium battery letter", note: "Lithium batteries in the shipment" });
  if (sectionII) {
    rows.push(
      { source: "paper", title: "Lithium battery mark on each package (Section II)", note: "No DGD and no hazard label for Section II" },
      { source: "auto", title: `AWB Handling Information: ${lithiumSectionIIStatement(input.lithiumPi)}`, note: "Printed on the AWB automatically" },
    );
  }
  if (input.dangerousGoods) {
    rows.push(
      {
        source: "paper",
        title: "Shipper's Declaration for Dangerous Goods (DGD)",
        note: "Two completed and signed copies from the shipper",
      },
      { source: "paper", title: "DG hazard labels and package markings", note: "Match the UN numbers. Use the Labels DG tab" },
      { source: "auto", title: "AWB Handling Information: Dangerous Goods as per associated DGD", note: "Printed on the AWB automatically" },
    );
  }
  rows.push(
    { source: "paper", title: "Client instructions / Shipper's Letter of Instruction", note: "Shipper" },
    { source: "paper", title: "Commercial invoice and packing list", note: "If the client provides them" },
    { source: "paper", title: "AES ITN or the NO EEI exemption", note: "ITN goes in Handling Information; blank prints NO EEI REQ 30.37(a)" },
  );
  return rows;
}

function goodsText(document: GuiaRecord): string {
  return document.lines.map((line) => plain(line.nature)).filter(Boolean).join(" ");
}

export function renderChecklist(document: GuiaRecord, company: CompanyView, options: GuiaPrintOptions): Promise<Buffer> {
  const awb = plain(document.awb);
  const unNumbers = plain(document.unNumbers);
  const rows = checklistRows({
    awb,
    bup: document.bup,
    dangerousGoods: document.dgDeclarable,
    unNumbers,
    lithiumPi: document.lithiumPi,
    goods: goodsText(document),
    hasTrucker: Boolean(plain(options.trucker ?? document.truckerName)),
  });
  const pieces = document.lines.reduce((sum, line) => sum + (line.pieces ?? 0), 0);
  const chargeable = document.lines.reduce((sum, line) => sum + (line.chargeableWeight ?? 0), 0);
  const logo = companyLogo(company);
  const when = new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", dateStyle: "medium", timeStyle: "short" }).format(options.now ?? new Date());

  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ size: "LETTER", margin: 0 });
    const chunks: Buffer[] = [];
    doc.on("data", (chunk: Buffer) => chunks.push(chunk));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);
    try {
      doc.info.Title = `CHECKLIST ${awb || "DRAFT"}`;
      const L = 40;
      const R = 572;
      const text = (value: string, x: number, y: number, size = 9, font = "Helvetica", width?: number) => {
        doc.font(font).fontSize(size).fillColor("#000000").text(value, x, y, { lineBreak: false, ...(width ? { width, ellipsis: true } : {}) });
      };
      try {
        doc.image(logo, L, 30, { fit: [120, 50] });
      } catch {
        /* The title still prints without the logo. */
      }
      text("SHIPMENT DOCUMENT CHECKLIST", 200, 36, 15, "Helvetica-Bold");
      text(`AWB ${awb || "DRAFT (not issued yet)"}`, 200, 58, 11);
      text(`Prepared ${when}`, 200, 74, 8);

      const flags: Array<[string, string]> = [
        ["BUP", document.bup ? "YES" : "NO"],
        ["Dangerous goods", document.dgDeclarable ? `YES ${unNumbers}`.trim() : "NO"],
      ];
      const facts: Array<[string, string]> = [
        ["Client", plain(document.guiaClient?.name) || plain(document.clientLabel)],
        ["Shipper", plain(document.shipperName)],
        ["Consignee", plain(document.consigneeName)],
        ["Route", [plain(document.departure), plain(document.destination)].filter(Boolean).join(" to ")],
        ["Flight", [plain(document.flightNumber), formatFlightDate(document.flightDate)].filter(Boolean).join("  ")],
        ["Pieces / chargeable kg", `${pieces || ""}${pieces && chargeable ? " / " : ""}${chargeable || ""}`],
        ["Trucker / driver / seal", [plain(options.trucker ?? document.truckerName), plain(options.driver ?? document.driverName), plain(options.seal ?? document.seal)].filter(Boolean).join(" / ")],
      ];
      let y = 100;
      doc.save().rect(L, y, R - L, 22).fill("#f1f5f9").restore();
      flags.forEach(([label, value], index) => {
        text(`${label}: `, L + 8 + index * 250, y + 7, 9, "Helvetica-Bold");
        text(value, L + 8 + index * 250 + doc.widthOfString(`${label}: `) + 2, y + 7, 9, value.startsWith("YES") ? "Helvetica-Bold" : "Helvetica");
      });
      y += 34;
      facts.forEach(([label, value], index) => {
        const column = index % 2;
        const row = Math.floor(index / 2);
        text(label, L + column * 270, y + row * 18, 7.5, "Helvetica-Bold");
        text(value, L + column * 270 + 105, y + row * 18, 9, "Helvetica", 160);
      });
      y += Math.ceil(facts.length / 2) * 18 + 14;

      doc.save().rect(L, y, R - L, 18).fill("#111827").restore();
      doc.fillColor("#ffffff");
      text("", L, y);
      doc.font("Helvetica-Bold").fontSize(8).fillColor("#ffffff");
      doc.text("OK", L + 8, y + 5, { lineBreak: false });
      doc.text("DOCUMENT", L + 40, y + 5, { lineBreak: false });
      doc.text("SOURCE", L + 300, y + 5, { lineBreak: false });
      doc.text("NOTES", L + 370, y + 5, { lineBreak: false });
      y += 18;
      rows.forEach((row, index) => {
        const top = y + index * 26;
        if (index % 2 === 1) doc.save().rect(L, top, R - L, 26).fill("#f8fafc").restore();
        doc.save().lineWidth(0.8).strokeColor("#111827").rect(L + 8, top + 8, 10, 10).stroke().restore();
        text(row.title, L + 40, top + 6, 9, "Helvetica-Bold", 255);
        text(row.source === "auto" ? "In this package" : "Collect", L + 300, top + 8, 8, "Helvetica", 66);
        text(row.note, L + 370, top + 8, 7.5, "Helvetica", R - L - 372);
      });
      y += rows.length * 26 + 6;
      doc.save().lineWidth(0.6).strokeColor("#9ca3af").moveTo(L, y).lineTo(R, y).stroke().restore();
      y += 28;
      text("Checked by: ____________________________", L, y, 9);
      text("Date: ________________", L + 290, y, 9);
    } catch (error) {
      reject(error);
      return;
    }
    doc.end();
  });
}
